/**
 * Unit tests for BeanDeserializerBase#deserializeFromBoolean
 */
public class BeanDeserializerBase_deserializeFromBoolean_TriageGen0Test {

    private JsonParser p;
    private DeserializationContext ctxt;
    private ValueInstantiator<?> valueInstantiator;
    private JsonDeserializer<Object> delegateDeserializer;
    private BeanDeserializerBase beanDeserializerBase;

    @Before
    public void setUp() {
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        valueInstantiator = mock(ValueInstantiator.class);
        delegateDeserializer = mock(JsonDeserializer.class);

        // Using a spy/subclass approach since BeanDeserializerBase is abstract and has protected constructor
        // We use a mock or a concrete subclass to test the logic
        beanDeserializerBase = new BeanDeserializerBase(null, null, null, null, null, false, false) {
            // We use reflection or internal field setting if possible, 
            // but here we simulate the state via a custom implementation for testing
        };
    }

    /**
     * Helper to create the class under test with specific internal states via reflection
     * because the fields are private/protected.
     */
    private BeanDeserializerBase createTestInstance(JsonDeserializer<Object> delegate, 
                                                    ValueInstantiator<?> instantiator, 
                                                    Object injectables) throws Exception {
        // Using a concrete subclass of BeanDeserializerBase for testing
        BeanDeserializerBase base = new BeanDeserializerBase(null, null, null, null, null, false, false) {
            @Override public JsonDeserializer<Object> unwrappingDeserializer(com.fasterxml.jackson.databind.NameTransformer unwrapper) { return null; }
            @Override protected BeanDeserializerBase asArrayDeserializer() { return null; }
            @Override public abstract Object deserializeFromObject(JsonParser p, DeserializationContext ctxt) throws IOException;
            @Override public abstract Object deserializeWithType(JsonParser p, DeserializationContext ctxt, com.fasterxml.jackson.databind.deser.std.TypeDeserializer typeDeserializer) throws IOException;
            @Override public abstract Object deserializeFromObjectUsingNonDefault(JsonParser p, DeserializationContext ctxt) throws IOException;
            @Override public abstract Object _deserializeUsingPropertyBased(JsonParser p, DeserializationContext ctxt) throws IOException, com.fasterxml.jackson.core.JsonProcessingException;
        };

        setField(base, "_delegateDeserializer", delegate);
        setField(base, "_valueInstantiator", instantiator);
        setField(base, "_injectables", injectables);
        return base;
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getSuperclass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testDeserializeFromBoolean_WithDelegateAndCanCreateFromBooleanTrue() throws Exception {
        // Case: _delegateDeserializer != null AND _valueInstantiator.canCreateFromBoolean() == true
        // Path: Falls through to the bottom of the method
        valueInstantiator = mock(ValueInstantiator.class);
        when(valueInstantiator.canCreateFromBoolean()).thenReturn(true);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_TRUE);

        Object expectedResult = "true_result";
        when(valueInstantiator.createFromBoolean(ctxt, true)).thenReturn(expectedResult);

        beanDeserializerBase = createTestInstance(mock(JsonDeserializer.class), valueInstantiator, null);

        Object result = beanDeserializerBase.deserializeFromBoolean(p, ctxt);

        assertEquals(expectedResult, result);
        verify(valueInstantiator).createFromBoolean(ctxt, true);
    }

    @Test
    public void testDeserializeFromBoolean_WithDelegateAndCanCreateFromBooleanFalse() throws Exception {
        // Case: _delegateDeserializer != null AND _valueInstantiator.canCreateFromBoolean() == false
        // Path: Uses delegate deserializer and creates using delegate
        JsonDeserializer<Object> delegate = mock(JsonDeserializer.class);
        valueInstantiator = mock(ValueInstantiator.class);

        when(valueInstantiator.canCreateFromBoolean()).thenReturn(false);
        when(delegate.deserialize(p, ctxt)).thenReturn("delegate_val");

        Object bean = "bean_instance";
        when(valueInstantiator.createUsingDelegate(ctxt, "delegate_val")).thenReturn(bean);

        beanDeserializerBase = createTestInstance(delegate, valueInstantiator, null);

        Object result = beanDeserializerBase.deserializeFromBoolean(p, ctxt);

        assertEquals(bean, result);
        verify(delegate).deserialize(p, ctxt);
        verify(valueInstantiator).createUsingDelegate(ctxt, "delegate_val");
    }

    @Test
    public void testDeserializeFromBoolean_WithDelegate_CanCreateFromBooleanFalse_WithInjectables() throws Exception {
        // Case: _delegateDeserializer != null AND _valueInstantiator.canCreateFromBoolean() == false AND _injectables != null
        // Path: Triggers injectValues
        JsonDeserializer<Object> delegate = mock(JsonDeserializer.class);
        valueInstantiator = mock(ValueInstantiator.class);
        Object injectables = new Object();

        when(valueInstantiator.canCreateFromBoolean()).thenReturn(false);
        when(delegate.deserialize(p, ctxt)).thenReturn("delegate_val");
        Object bean = new Object();
        when(valueInstantiator.createUsingDelegate(ctxt, "delegate_val")).thenReturn(bean);

        // We need to spy the base to verify injectValues was called
        BeanDeserializerBase realBase = createTestInstance(delegate, valueInstantiator, injectables);
        BeanDeserializerBase spyBase = spy(realBase);

        Object result = spyBase.deserializeFromBoolean(p, ctxt);

        assertEquals(bean, result);
        verify(spyBase).injectValues(eq(ctxt), eq(bean));
    }

    @Test
    public void testDeserializeFromBoolean_NoDelegate_True() throws Exception {
        // Case: _delegateDeserializer == null
        // Path: Goes to bottom, checks token == VALUE_TRUE
        valueInstantiator = mock(ValueInstantiator.class);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_TRUE);
        when(valueInstantiator.createFromBoolean(ctxt, true)).thenReturn("true_obj");

        beanDeserializerBase = createTestInstance(null, valueInstantiator, null);

        Object result = beanDeserializerBase.deserializeFromBoolean(p, ctxt);

        assertEquals("true_obj", result);
    }

    @Test
    public void testDeserializeFromBoolean_NoDelegate_False() throws Exception {
        // Case: _delegateDeserializer == null, token is not VALUE_TRUE
        valueInstantiator = mock(ValueInstantiator.class);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_FALSE);
        when(valueInstantiator.createFromBoolean(ctxt, false)).thenReturn("false_obj");

        beanDeserializerBase = createTestInstance(null, valueInstantiator, null);

        Object result = beanDeserializerBase.deserializeFromBoolean(p, ctxt);

        assertEquals("false_obj", result);
    }

    @Test
    public void testDeserializeFromBoolean_NoDelegate_OtherToken() throws Exception {
        // Case: _delegateDeserializer == null, token is something else
        valueInstantiator = mock(ValueInstantiator.class);
        when(p.getCurrentToken()).thenReturn(JsonToken.START_OBJECT);
        when(valueInstantiator.createFromBoolean(ctxt, false)).thenReturn("false_obj");

        beanDeserializerBase = createTestInstance(null, valueInstantiator, null);

        Object result = beanDeserializerBase.deserializeFromBoolean(p, ctxt);

        assertEquals("false_obj", result);
    }
}
